"""Self-contained retrieval report; all percentages are derived from saved scores."""
from pathlib import Path
import json,html,csv,hashlib
O=Path(__file__).resolve().parents[3]/'outputs/embedding_ablation/financebench50_300_0_20261013'
MODELS=['bge-small','qwen3-0.6b']
def read(name):return json.loads((O/name).read_text())
def main():
 summary=read('summary.json');assert all(m in summary for m in MODELS),'Both model runs must finish before final report'
 cases=read('selected_cases.json');criteria=read('evidence_criteria.json');common=read('config.json')
 data={'summary':summary,'cases':cases,'criteria':criteria,'config':common,'paired':read('paired_comparison.json'),
       'results':{m:read(m+'/results.json') for m in MODELS},'audit':read('evidence_reachability.json'),
       'manual':read('manual_review.json') if (O/'manual_review.json').exists() else None,'precision':{m:read(m+'/precision_audit.json') for m in MODELS},'scoring':read('scoring_manifest.json')}
 with (O/'results.csv').open('w',newline='') as f:
  w=csv.writer(f);w.writerow(['model','cohort','mode','questions','content_evaluable','page_hit','page_coverage','content_hit','content_unit_coverage','all_units','page_hit_without_content'])
  for m in MODELS:
   for cohort in ['all50','old10','new40']:
    for mode in ['top5','top10','top20','budget2000']:
     s=summary[m][cohort][mode];w.writerow([m,cohort,mode]+[s[k] for k in ['questions','content_evaluable','page_hit','page_coverage','content_hit','content_coverage','content_all','page_hit_no_content']])
 with (O/'case_results.csv').open('w',newline='') as f:
  w=csv.writer(f);w.writerow(['model','case_id','cohort','mode','page_hit','page_coverage','content_hit','content_coverage','all_units','missing_units','manual_required'])
  for m in MODELS:
   for r in data['results'][m]:
    for mode in ['top5','top10','top20','budget2000']:
     s=r[mode];c=s['content'];w.writerow([m,r['id'],r['cohort'],mode,s['hit'],s['coverage'],c['hit'],c['coverage'],c['all_units'],','.join(c['missing_units']),c['manual_required']])
 payload=json.dumps(data,ensure_ascii=False).replace('</','<\\/')
 template=r'''<!doctype html><html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>FinanceBench 50 · 证据内容检索对比</title><style>
:root{--ink:#172b3a;--muted:#647687;--line:#dbe3e9;--blue:#216bcb;--green:#008d7a;--bg:#f3f6f9}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.7 -apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC",sans-serif}main{max-width:1180px;margin:auto;padding:30px 30px 80px}header{background:#112d44;color:white;padding:40px;border-radius:20px}header .eyebrow{color:#90c4ed;letter-spacing:2px;font-size:12px}h1{font-size:32px;line-height:1.35;margin:12px 0}h2{font-size:21px;margin:0 0 12px}h3{font-size:16px;margin:12px 0 6px}p{margin:8px 0}header p{color:#d4e2ed;max-width:900px}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:22px 0}.card,section{background:white;border:1px solid var(--line);border-radius:14px;padding:22px}.card b{display:block;font-size:28px;line-height:1.4}.card span,.muted{color:var(--muted);font-size:13px}section{margin:18px 0}.notice{background:#eef5fd;border-left:4px solid var(--blue);padding:16px 20px;border-radius:6px}.warn{background:#fff7e9;border-left-color:#c68e31}.controls{display:flex;flex-wrap:wrap;align-items:center;gap:12px;margin:16px 0}select,input{font:inherit;padding:7px 10px;border:1px solid #c3d1dd;border-radius:7px;background:white;color:var(--ink)}table{width:100%;border-collapse:collapse;font-size:14px}th,td{text-align:left;padding:11px 10px;border-bottom:1px solid var(--line);vertical-align:top}th{background:#f5f8fb;font-size:12px;color:#526c80;white-space:nowrap}.tablewrap{overflow:auto}.tag{display:inline-block;background:#edf2f7;border-radius:4px;padding:1px 7px;font-size:12px;color:#587084;margin-right:6px}.green{color:var(--green)}.blue{color:var(--blue)}.chart{display:grid;grid-template-columns:1fr 1fr 1fr;gap:25px;margin-top:20px}.bar{height:14px;background:#eef2f7;border-radius:3px;overflow:hidden;margin:5px 0 11px}.fill{height:100%;background:var(--blue)}.fill.qwen{background:var(--green)}.barlabel{display:flex;justify-content:space-between;font-size:12px}details.case{border:1px solid var(--line);border-radius:9px;margin:10px 0;padding:0 15px}summary{cursor:pointer;padding:13px 0;font-weight:600;overflow-wrap:anywhere}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:18px}.casebody{padding-bottom:20px}.question{font-size:16px;background:#f5f8fa;padding:12px 16px;border-radius:7px}.snippet{white-space:pre-wrap;overflow-wrap:anywhere;font:12px/1.6 ui-monospace,SFMono-Regular,monospace;background:#f4f7fa;padding:10px;border-radius:5px;max-height:210px;overflow:auto}.unit{padding:7px 0;border-bottom:1px solid #edf1f4}.ok{color:#007867}.bad{color:#ad4f36}a{color:var(--blue)}code{font-size:12px;overflow-wrap:anywhere}.foot{font-size:12px;color:#788995}.mini{font-size:12px}.status{font-size:13px;margin-top:5px}.k{font-variant-numeric:tabular-nums}footer{padding:12px;font-size:12px;color:#758695}@media(max-width:800px){main{padding:15px}header{padding:24px}h1{font-size:25px}.cards{grid-template-columns:repeat(2,1fr)}.chart,.grid2{grid-template-columns:1fr}section{padding:17px}}
</style></head><body><main>
<header><div class="eyebrow">RETRIEVAL EXPERIMENT · FINANCEBENCH · 2026-10-13</div><h1>从“找对页”到“找到证据”<br>BGE-small 与 Qwen · 50 题复测</h1><p>固定 300 tokens / overlap 0，扩大文档干扰项，逐题核验金融指标与原文事实。仅评估检索；不生成答案，也不计回答准确率。</p></header>
<div class="cards"><div class="card"><b>50 <small>题</small></b><span>原 10 题 + 新增 40 题</span></div><div class="card"><b>41 <small>份</small></b><span id="pageCount"></span></div><div class="card"><b>18,806</b><span>同一组固定文本分块</span></div><div class="card"><b>116</b><span>证据单元 · 49 题可自动核验</span></div></div>
<section><h2>本轮读数</h2><div id="takeaway" class="notice"></div><p class="muted">“有效命中”指通过下述内容规则的至少一个事实单元；“找全”仅指本轮标注的全部单元均被覆盖，不等于模型已能正确回答。以下默认展示 Top-5，可切换检索深度或 2,000-token 上下文预算。</p>
<div class="controls"><label>样本 <select id="cohort"><option value="all50">全部 50 题</option><option value="old10">原 10 题（扩大后语料）</option><option value="new40">新增 40 题</option></select></label><label>检索范围 <select id="mode"><option value="top5">Top-5</option><option value="top10">Top-10</option><option value="top20">Top-20</option><option value="budget2000">2,000 tokens 预算</option></select></label></div>
<div class="tablewrap"><table><thead><tr><th>模型</th><th>页码命中率</th><th>有效证据命中率</th><th>证据单元覆盖率</th><th>全部单元找全率</th><th>有页码 / 无有效内容</th></tr></thead><tbody id="metrics"></tbody></table></div><div id="charts" class="chart"></div><p id="denominator" class="muted"></p><p id="paired" class="notice"></p></section>
<section><h2>如何防止“页脚也算命中”</h2><div class="grid2"><div><h3>按内容给分</h3><p>数值题要求<strong>具体财务行名 + 精确金额</strong>在局部文本内同时存在；计算题拆成所需输入。文字题匹配具有实质意义的原文，包括关键否定词。只有报告名、页码或表头，不能获得有效内容分。</p><p>证据必须来自标注的文档和页码。同一事实单元可跨<strong>已返回且原文相邻</strong>的分块拼接；不补齐未返回内容，不跨页拼接。不同单元可以由多个片段分别支持。</p></div><div><h3>规则与原文的可达性</h3><p>116 / 116 单元可在参考证据及解析原页中匹配；111 / 116 可在单个 300-token 分块中匹配。其余 5 个需要多个相邻分块共同返回。</p><p>Verizon 流动负债合计存在 PDF 阅读顺序变化，规则保留局部逆序匹配。所有规则在本轮模型排名核验前冻结，并记录哈希；未按模型胜负修改标准。</p></div></div><div class="notice warn"><strong>1 题采用独立版面复核：</strong>Ulta “是否没有收购”涉及表格的空白值和年份列，文本中找不到金额并不能证明没有收购。该题保留在 50 题页码指标中，但不进入自动内容指标分母（49 题）。</div><div id="manualReview"></div></section>
<section><h2>值得复查的具体案例</h2><p><strong>Verizon · 00216：</strong>Qwen 的首位返回仅为“Verizon 2022 Annual Report on Form 10-K 56”。旧页码指标给分，本轮内容规则不给分。</p><p><strong>Corning · 10130：</strong>Qwen 的 Top-5 找到成本、库存及应付账款；BGE-small 找到后两项，缺成本。这里的改善有具体财务行支撑。</p><p><strong>Ulta SG&A · 00601：</strong>BGE-small 的 Top-5 覆盖两个原因，Qwen 没有覆盖。模型优势并不逐题成立。</p><p><strong>Best Buy 现金 · 00288：</strong>Qwen 返回了 1,093 / 1,874，但财务行名和完整年度表头位于前面的分块。严格规则未通过；这类片段仍可能有用，需检查相邻块与表格上下文，不能简单等同于“检索内容完全无关”。</p></section><section><h2>运行配置与资源记录</h2><div class="tablewrap"><table><thead><tr><th>模型</th><th>维度 / 向量体积</th><th>文档编码耗时</th><th>50 条查询批量编码</th><th>文档 / 查询截断数</th><th>与原 FP32 向量最小相似度</th></tr></thead><tbody id="runtime"></tbody></table></div><p>所有分块和 2,000-token 预算统一按 BGE-small tokenizer 计数，两个模型读取完全相同的文本；Qwen 自己的 token 数会不同。查询使用原始英文问题，并追加已知的目标报告文件名；BGE 使用推荐查询前缀，Qwen 使用模型内置 query 指令。答案与标注页码不进入查询。检索在全部 41 份报告中进行，不做文档过滤、BM25、重排或查询改写；因此本轮结论限定于已知报告身份的提问条件。</p><p>两者在同一台机器上顺序运行，使用 MPS、FP16、batch 8。输出转为 FP32 再归一化，以精确内积排序；中间分块缓存支持续跑。半精度核验使用原语料固定位置的 64 个片段，不能保证所有查询的名次完全不变。</p><p class="muted">耗时是本机实测文档编码时间（不含加载、解析和精度核验），不是跨硬件基准。查询列是 50 条一起编码的总时间，不是单请求延迟；向量体积只含最终向量数组，不含模型和中间缓存。</p></section>
<section><h2>逐题证据审计</h2><p class="muted">展开可看原题、参考答案、必需证据、两模型匹配片段，以及实际返回文本。参考答案只用于定义核验标准，没有进入检索查询。</p><div class="controls"><input id="search" placeholder="搜索公司、题号或问题" aria-label="搜索案例"><select id="filter"><option value="all">所有案例</option><option value="pageonly">至少一方：页码命中但无内容</option><option value="qwen">Qwen 内容覆盖更高</option><option value="bge">BGE 内容覆盖更高</option><option value="manual">需要人工核验</option></select><span id="caseCount" class="muted"></span></div><div id="caseList"></div></section>
<section><h2>实验边界与下一步</h2><p>样本来自 FinanceBench 公开 150 题：保留原 10 题，按固定随机种子补至 50 题；题型配额为 metrics 17、domain 17、novel 16。41 份完整报告参与全局检索，无文档过滤；10 份旧文档的 5,586 个分块保持逐字段一致。新旧问答共用扩大后的检索库，因此旧题本轮成绩不能直接与上轮 10 份文档的成绩做因果比较。</p><p>这 50 题已用于规则开发，不是未见测试集。规则依据参考答案与证据编写，尚未经过独立金融专家标注；局部文本匹配能排除明显无关片段，但<strong>没有完整恢复表格的年份列、单位与跨页语义</strong>。同页局部共现仍可能误报，标注页外的等价证据也可能被漏计。</p><p>AMEX 指标适用性、资本密集型判断，以及 3M / Amcor 的不完整参考答案，评分仅核验给出的支持依据；Paypal 营运资本和 MGM 负利息覆盖率存在参考口径限制。逐题已列明备注，不把“单元找全”解释为充分回答所有问题。</p><p>下一步先抽查两模型有分歧及页码假命中的案例，校验列头—年份—数值关系；再固定这些规则，用未参与开发的新题复测。需要提升召回时，可独立对比相邻块扩展、混合检索或 reranker，不与本轮 embedding 变更混在一起。</p></section>
<section><h2>可复现材料</h2><p><a href="results.csv">汇总结果 CSV</a> · <a href="case_results.csv">逐题指标 CSV</a> · <a href="evidence_criteria.json">逐题证据规则</a> · <a href="evidence_reachability.json">原页 / 分块可达性</a> · <a href="scoring_manifest.json">评分版本与哈希</a> · <a href="bge-small/precision_ranking_audit.json">BGE 精度 / 排序核验</a> · <a href="qwen3-0.6b/precision_ranking_audit.json">Qwen 精度 / 排序核验</a> · <a href="config.json">样本与语料配置</a></p><p><a href="https://github.com/patronus-ai/financebench/tree/cc39aeb4afdf33909ee1412188bf89035950c2eb">固定版本 FinanceBench 数据源</a> · <a href="https://huggingface.co/BAAI/bge-small-en-v1.5">BGE-small 模型卡</a> · <a href="https://huggingface.co/Qwen/Qwen3-Embedding-0.6B">Qwen 模型卡</a></p><p class="foot" id="fingerprint"></p></section><footer>金融 PDF RAG · 50 题检索实验。报告完全本地，不调用回答模型。</footer>
</main><script id="experimentData" type="application/json">__DATA__</script><script>
const D=JSON.parse(document.getElementById('experimentData').textContent),names=['bge-small','qwen3-0.6b'],labels=['BGE-small','Qwen3-Embedding-0.6B'];
const $=id=>document.getElementById(id),pct=x=>x===null?'不自动计分':(x*100).toFixed(1)+'%',esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
$('pageCount').textContent=D.config.pages.toLocaleString()+' 页完整报告参与检索';
const a=D.summary[names[0]].all50.top5,b=D.summary[names[1]].all50.top5;
const better=b.content_coverage>a.content_coverage?'Qwen':'BGE-small';const ba=D.summary[names[0]].all50.budget2000,bb=D.summary[names[1]].all50.budget2000;
$('takeaway').innerHTML=`在本轮 Top-5 检索中，<strong>${better} 的平均证据单元覆盖率较高</strong>：BGE-small 为 ${pct(a.content_coverage)}，Qwen 为 ${pct(b.content_coverage)}。真正找全全部标注单元的比例分别为 ${pct(a.content_all)} 和 ${pct(b.content_all)}。页码命中率分别为 ${pct(a.page_hit)} / ${pct(b.page_hit)}，不能当作有效证据命中率。<p><strong>统一 2,000-token 预算时，差距明显缩小：</strong>证据覆盖率为 ${pct(ba.content_coverage)} / ${pct(bb.content_coverage)}，全部找全率为 ${pct(ba.content_all)} / ${pct(bb.content_all)}。Top-5 覆盖差异的探索性区间包含零，这批开发题尚不足以证明稳定优势。</p>`;
$('runtime').innerHTML=names.map((m,i)=>{let s=D.summary[m],e=s.encoding,t=s.token_audit;return `<tr><td><strong>${labels[i]}</strong></td><td>${e.dimension} / ${(e.vector_bytes/1048576).toFixed(1)} MiB</td><td>${(e.encoding_seconds/60).toFixed(2)} 分钟</td><td>${e.query_batch_seconds.toFixed(2)} 秒</td><td>${t.document_truncation_count} / ${t.query_truncation_count}</td><td>${D.precision[m].cosine_min.toFixed(7)}</td></tr>`}).join('');
$('fingerprint').textContent='证据规则 SHA-256：'+D.scoring.criteria_sha256;
function render(){let co=$('cohort').value,mo=$('mode').value,ss=names.map(m=>D.summary[m][co][mo]);
$('metrics').innerHTML=ss.map((s,i)=>`<tr><td><strong class="${i?'green':'blue'}">${labels[i]}</strong></td><td>${pct(s.page_hit)}</td><td><strong>${pct(s.content_hit)}</strong></td><td><strong>${pct(s.content_coverage)}</strong></td><td>${pct(s.content_all)}</td><td>${s.page_hit_no_content} 题</td></tr>`).join('');
$('charts').innerHTML=[['content_hit','至少一个有效单元'],['content_coverage','平均证据单元覆盖'],['content_all','全部单元找全']].map(([k,title])=>`<div><h3>${title}</h3>${ss.map((s,i)=>`<div class="barlabel"><span>${labels[i]}</span><b>${pct(s[k])}</b></div><div class="bar"><div class="fill ${i?'qwen':''}" style="width:${100*s[k]}%"></div></div>`).join('')}</div>`).join('');
$('denominator').textContent=`页码指标分母 ${ss[0].questions} 题；内容指标分母 ${ss[0].content_evaluable} 题。覆盖率按题平均，各题等权。“有页码 / 无有效内容”仅统计可自动核验题。平均返回内容 tokens：BGE ${ss[0].used_tokens_mean.toFixed(0)} / Qwen ${ss[1].used_tokens_mean.toFixed(0)}。`;
const p=D.paired[co][mo];$('paired').textContent=`逐题比较证据覆盖率：Qwen 更高 ${p.qwen_better} 题，持平 ${p.equal} 题，BGE 更高 ${p.bge_better} 题。Qwen − BGE 平均差 ${(100*p.mean_delta).toFixed(1)} 个百分点；按题配对 bootstrap 95% 区间 [${p.question_bootstrap_95ci.map(x=>(100*x).toFixed(1)).join(', ')}]。这是探索性区间；同文档问题相关，不能据此宣称普遍优势。`;
if(D.manual){const mr=D.manual;$('manualReview').innerHTML='<details><summary>Ulta 原表版面与检索复核</summary><p>'+esc(mr.source_finding)+'</p>'+names.map((m,i)=>'<p><b>'+labels[i]+'</b> · '+esc(mr.models[m][mo].assessment)+'</p>').join('')+'<p class="muted">PDF 第 57 页（印刷页 54）。本项在自动规则冻结后单独记录，不修改汇总分数。</p><img src="'+esc(mr.image)+'" alt="Ulta 现金流量表原页，含年度列与收购行" style="width:100%;max-width:800px"></details>';}
renderCases();}
function renderCases(){let mo=$('mode').value,co=$('cohort').value,filter=$('filter').value,term=$('search').value.trim().toLowerCase();let count=0;
$('caseList').innerHTML=D.cases.map((c,i)=>{let r=D.criteria[i],rows=names.map(m=>D.results[m][i]),cs=rows.map(x=>x[mo].content);
if(co!=='all50'&&rows[0].cohort!==co)return '';if(term&&!JSON.stringify([c.company,c.financebench_id,c.question,c.doc_name]).toLowerCase().includes(term))return '';
if(filter==='manual'&&!r.manual_required)return '';if(filter==='pageonly'&&!rows.some(x=>x[mo].page_hit_no_content))return '';if(filter==='qwen'&&!(cs[1].coverage>cs[0].coverage))return '';if(filter==='bge'&&!(cs[0].coverage>cs[1].coverage))return '';count++;
let units=r.units.map(u=>`<div class="unit"><span class="tag">${esc(u.id)} · p.${u.pages.join(', ')}</span>${esc(u.label)}</div>`).join('');
let body=names.map((m,j)=>{let rr=rows[j],cc=cs[j],s=rr[mo];let matched=cc.matches.map(x=>`<div><span class="ok">✓ ${esc(x.label)}</span> <span class="mini">p.${x.page} · ${x.chunk_ids.length>1?'相邻 '+x.chunk_ids.length+' 块 · ':''}最迟 rank ${x.rank}</span><div class="snippet">${esc(x.span.text)}</div></div>`).join('');
let ranking=rr.ranking.slice(0,s.chunks).map(x=>`<details><summary class="mini">#${x.rank} · ${esc(x.document_id)} · p.${x.page} ${x.gold_page?'[标注页]':''} ${x.individual_content_units.length?'[独立单元 '+esc(x.individual_content_units.join(','))+']':''}</summary><div class="snippet">${esc(x.text)}</div></details>`).join('');
return `<div><h3 class="${j?'green':'blue'}">${labels[j]}</h3><p class="status">页码命中 ${s.hit?'是':'否'} · 内容覆盖 ${pct(cc.coverage)} · 全部找全 ${cc.all_units===null?'不自动计分':cc.all_units?'是':'否'}</p>${matched||'<p class="muted">此范围内没有通过规则的实质证据。</p>'}<p class="mini bad">缺失单元：${cc.missing_units.length?esc(cc.missing_units.join(', ')):(r.manual_required?'需核对空白值与年度列':'无')}</p><details><summary>查看返回的 ${s.chunks} 个片段</summary>${ranking}</details></div>`}).join('');
return `<details class="case"><summary><span class="tag">${String(i+1).padStart(2,'0')} · ${rows[0].cohort==='old10'?'原题':'新增'}</span>${esc(c.company)} · ${esc(c.financebench_id.replace('financebench_id_',''))}<div class="muted">内容覆盖 BGE ${pct(cs[0].coverage)} / Qwen ${pct(cs[1].coverage)}</div></summary><div class="casebody"><div class="question">${esc(c.question)}</div><p><b>参考答案：</b>${esc(c.answer)}</p><p class="mini">报告：${esc(c.doc_name)}</p>${r.note?'<p class="notice warn">'+esc(r.note)+'</p>':''}<details><summary>本题核验标准与原始参考证据</summary>${units}${c.evidence.map(e=>`<h3>参考证据 · PDF p.${e.evidence_page_num+1}</h3><div class="snippet">${esc(e.evidence_text)}</div>`).join('')}</details><div class="grid2">${body}</div></div></details>`;
}).join('');$('caseCount').textContent=count+' 题';}
['cohort','mode'].forEach(x=>$(x).addEventListener('change',render));$('filter').addEventListener('change',renderCases);$('search').addEventListener('input',renderCases);render();
</script></body></html>'''
 (O/'report.html').write_text(template.replace('__DATA__',payload))
